"""Temporal candidate policy for safe target-directed motion."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or forward motion has material collision risk."""
    if (
        float(observation.get("safety_confidence", 0.0)) < 0.60
        or float(observation.get("closing_risk", 1.0)) >= 0.75
    ):
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Require stable target identity and use bounded stopping scans after target loss."""
    visible = bool(observation.get("target_visible", False))
    reliable = (
        visible
        and float(observation.get("target_confidence", 0.0)) >= 0.55
        and float(observation.get("target_identity_confidence", 0.0)) >= 0.60
    )
    if not reliable:
        lost_steps = int(observation.get("lost_steps", 99))
        if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
            memory["state"] = "REACQUIRE"
            return "STOP", 0.92
        direction = memory.get("scan_direction", "SCAN_LEFT")
        memory["scan_direction"] = (
            "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        memory["state"] = "SEARCH"
        return direction, 0.75
    if int(observation.get("track_age", 0)) < 2:
        memory["state"] = "VERIFY"
        return "SLOW_DOWN", 0.80
    return None


def propose_moves(observation, memory):
    """Build an ordered, observation-supported action set with directional preference."""
    bearing = float(observation.get("target_bearing", 0.0))
    candidates = []
    if bearing < -12.0 and observation.get("corridor_left", False):
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and observation.get("corridor_right", False):
        candidates.append("VEER_RIGHT")
    if observation.get("corridor_center", False):
        candidates.append("FORWARD")
    if observation.get("corridor_left", False):
        candidates.append("VEER_LEFT")
    if observation.get("corridor_right", False):
        candidates.append("VEER_RIGHT")
    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Use bounded temporal hysteresis to favor progress and suppress turn oscillation."""
    if not candidates:
        return None

    distance = observation.get("target_distance_class", "far")
    rank = {"far": 0, "medium": 1, "near": 2}.get(distance, 0)
    previous_rank = memory.get("distance_rank")
    stale = int(memory.get("stale_steps", 0))
    if previous_rank is None or rank > previous_rank:
        stale = 0
    else:
        stale = min(stale + 1, 4)
    memory["distance_rank"] = rank
    memory["stale_steps"] = stale

    bearing = float(observation.get("target_bearing", 0.0))
    heading = abs(float(observation.get("heading_error", 0.0)))
    desired = (
        "VEER_LEFT" if bearing < -8.0 else
        "VEER_RIGHT" if bearing > 8.0 else
        "FORWARD"
    )

    last = memory.get("last_action")
    scores = {}
    for action in candidates:
        score = 0.0
        if action == desired:
            score += 3.0
        if action == "FORWARD":
            score += max(0.0, 1.5 - abs(bearing) / 20.0)
            score -= heading / 90.0
        else:
            score += min(abs(bearing) / 30.0, 1.5)
        if last and action != last and stale < 2:
            score -= 0.8
        if stale >= 2 and action == desired:
            score += 1.2
        scores[action] = score

    action = max(candidates, key=lambda item: scores[item])
    memory["last_action"] = action
    return action


def termination_contract(observation, memory):
    """Return a conservative stop when no safe, observable motion proposal exists."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination into three outputs."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    distance = observation.get("target_distance_class", "far")
    identity = float(observation.get("target_identity_confidence", 0.0))
    heading_error = abs(float(observation.get("heading_error", 0.0)))

    if distance == "near" and heading_error <= 15.0 and identity >= 0.80:
        memory["state"] = "ARRIVED"
        return "ARRIVED", 0.96, memory

    if distance == "near":
        bearing = float(observation.get("target_bearing", 0.0))
        candidates = [
            "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        ]
        candidates = [
            action for action in candidates
            if (
                action == "VEER_LEFT" and observation.get("corridor_left", False)
            ) or (
                action == "VEER_RIGHT" and observation.get("corridor_right", False)
            )
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
